(() => {
  'use strict';
  const $=id=>document.getElementById(id);
  const concepts={'1':['선택형 · 3페이지','사무실과 도시 전망 · 정책자금 / 정부지원사업 / 진행절차 / 간편상담.'],'2':['대화형 · 4페이지','1:1 컨설턴트 상담 · 자금안내 / 진행절차 / 간편상담.'],'5':['제안형 · 3페이지','저녁 도시 전망 · 정책자금 / 정부지원사업 / 진행절차 / 간편상담.'],'compare':['비교 탐색형 · 3페이지','컨설턴트 회의 · 홈 / 자금비교 / 간편상담.'],'brief':['장면형 브리핑 · 3페이지','창가 컨설턴트 · 브리핑 / 자금안내 / 상담준비 / 간편상담.']};
  document.querySelectorAll('[data-concept]').forEach(button=>button.addEventListener('click',()=>{
    document.querySelectorAll('.concept').forEach(c=>c.hidden=c.id!=='concept-'+button.dataset.concept);
    document.querySelectorAll('[data-concept]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
    const text=concepts[button.dataset.concept];$('concept-name').textContent=text[0];$('concept-description').textContent=text[1];window.scrollTo({top:0,behavior:'instant'});
  }));
  $('mono-toggle').addEventListener('change',event=>document.body.classList.toggle('mono-view',event.target.checked));
  document.querySelectorAll('[data-open-form]').forEach(button=>button.addEventListener('click',()=>{$('form-result').hidden=true;$('consult-dialog').showModal();}));
  document.querySelectorAll('[data-open-privacy]').forEach(button=>button.addEventListener('click',()=>$('privacy-dialog').showModal()));
  document.querySelectorAll('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
  document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}));
  $('consult-form').addEventListener('submit',event=>{event.preventDefault();$('form-result').hidden=false;$('form-result').scrollIntoView({block:'nearest',behavior:'instant'});});
  $('phone').addEventListener('input',event=>{const value=event.target.value.replace(/\D/g,'');event.target.setCustomValidity(value.length>=9&&value.length<=11?'':'연락 가능한 전화번호를 확인해 주세요.');});
  ['name','company'].forEach(id=>$(id).addEventListener('input',event=>event.target.setCustomValidity(event.target.value.trim()?'':'내용을 입력해 주세요.')));
})();

(() => {const guide=document.getElementById('guide-dialog');document.querySelectorAll('[data-open-guide]').forEach(b=>b.addEventListener('click',()=>guide.showModal()));document.querySelector('[data-guide-consult]').addEventListener('click',()=>{guide.close();document.getElementById('form-result').hidden=true;document.getElementById('consult-dialog').showModal();});})();
(() => {document.querySelectorAll('[data-inline-contact-form]').forEach(form=>{
 const name=form.dataset.inlineContactForm;
 form.addEventListener('submit',event=>{event.preventDefault();const result=form.querySelector('[data-inline-result]');result.hidden=false;result.scrollIntoView({block:'nearest',behavior:'instant'});});
 form.querySelector('[name=phone]').addEventListener('input',event=>{const digits=event.target.value.replace(/\D/g,'');event.target.setCustomValidity(digits.length>=9&&digits.length<=11?'':'연락 가능한 전화번호를 확인해 주세요.');});
 ['name','company'].forEach(field=>form.querySelector('[name='+field+']').addEventListener('input',event=>event.target.setCustomValidity(event.target.value.trim()?'':'내용을 입력해 주세요.')));
});})();

(() => {
 'use strict';
 function message(input){
  if(input.type==='checkbox')return input.required&&!input.checked?'개인정보 수집·이용에 동의해 주세요.':'';
  const value=input.value.trim();
  if(input.name==='name')return value?'':'이름을 입력해 주세요.';
  if(input.name==='company')return value?'':'회사명 또는 상호를 입력해 주세요.';
  if(input.name==='region')return value?'':'사업장 지역을 선택해 주세요.';
  if(input.name==='industry')return value?'':'주요 업종을 선택해 주세요.';
  if(input.name==='phone'){
   const digits=value.replace(/\D/g,'');
   return /^[+]?[-\d\s().]+$/.test(value)&&digits.length>=8&&digits.length<=15?'':'연락 가능한 전화번호를 확인해 주세요.';
  }
  return input.required&&!value?'필수 정보를 확인해 주세요.':'';
 }
 document.querySelectorAll('#consult-form,[data-inline-contact-form]').forEach(form=>{
  if(form.dataset.v7Validated)return;form.dataset.v7Validated='true';form.noValidate=true;
  const inputs=[...form.querySelectorAll('input,select')];
  const summary=document.createElement('div');summary.className='validation-summary';summary.setAttribute('role','alert');summary.hidden=true;form.prepend(summary);
  function paint(input,text){
   input.setCustomValidity(text);
   if(!input.id)input.id=form.id+'-'+input.name;
   const id=input.id+'-validation';let error=document.getElementById(id);
   if(!error){error=document.createElement('p');error.id=id;error.className='validation-message';error.hidden=true;const container=input.closest('.field')||input.closest('.consent');container.insertAdjacentElement('afterend',error);if(input.closest('.field'))input.closest('.field').append(error);}
   if(text){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',id);if(error.textContent!==text)error.textContent=text;error.hidden=false;}
   else{input.removeAttribute('aria-invalid');input.removeAttribute('aria-describedby');error.hidden=true;}
  }
  function updateSummary(){const errors=inputs.filter(i=>message(i));summary.hidden=!errors.length;if(errors.length&&summary.textContent!=='입력 내용을 확인해 주세요. 표시된 항목을 수정하면 상담 흐름을 이어갈 수 있습니다.')summary.textContent='입력 내용을 확인해 주세요. 표시된 항목을 수정하면 상담 흐름을 이어갈 수 있습니다.';}
  inputs.forEach(input=>{
   function changed(){const text=message(input);input.setCustomValidity(text);if(form.dataset.validationAttempted){paint(input,text);updateSummary();}}
   input.addEventListener('input',changed);input.addEventListener('change',changed);
  });
  form.addEventListener('submit',event=>{
   event.preventDefault();form.dataset.validationAttempted='true';const invalid=[];
   inputs.forEach(input=>{const text=message(input);paint(input,text);if(text)invalid.push(input);});updateSummary();
   if(invalid.length){event.stopImmediatePropagation();const result=form.querySelector('.form-result');if(result)result.hidden=true;invalid[0].focus({preventScroll:true});invalid[0].scrollIntoView({block:'center',behavior:'instant'});}
  },true);
 });
})();
